        lda button_press_edge
        pha
        lda #$00
        sta button_press_edge
        pla
        cmp #$00
        rts
; A is 1 when the pad is not touched for 16 samples (off_pad_count) and a button is held: the gesture that changes between the menu and the picture.
long_press_off_pad
