        beq long_press_none
        lda off_pad_count
        cmp #$10
        bcc long_press_none
        lda #$00
        sta off_pad_count
        lda #$01
        rts
long_press_none
        lda #$00
        rts
; Gives button_held in A: 1 while a pad button is down.
